<?php require __DIR__.'/_layout.php';$u=require_admin();$pdo=db();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$act=$_POST['action']??'save';if($act==='delete'){$id=(int)$_POST['id'];$st=$pdo->prepare("SELECT photo_path FROM people WHERE id=?");$st->execute([$id]);$old=(string)$st->fetchColumn();$pdo->prepare("DELETE FROM people WHERE id=?")->execute([$id]);delete_local_media($old);go('pessoas.php','Pessoa removida.');}$photo='';if(!empty($_FILES['photo']['name']))$photo=upload_file($_FILES['photo'],'image');$pdo->prepare("INSERT INTO people(name,role,group_type,biography,photo_path,instagram_url,sort_order,published) VALUES(?,?,?,?,?,?,?,?)")->execute([trim($_POST['name']??''),trim($_POST['role']??''),($_POST['group_type']??'INTEGRANTE')==='COORDENACAO'?'COORDENACAO':'INTEGRANTE',trim($_POST['biography']??''),$photo,trim($_POST['instagram_url']??''),(int)($_POST['sort_order']??100),isset($_POST['published'])?1:0]);go('pessoas.php','Pessoa cadastrada.');}catch(Throwable $e){$err=$e->getMessage();}}$rows=$pdo->query("SELECT * FROM people ORDER BY group_type,sort_order,name")->fetchAll();admin_header('Coordenação e Integrantes');$msg=flash();?>
<?php if($msg):?><div class="alert ok"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?>
<form class="panel form-stack" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><h2>Adicionar pessoa</h2><div class="grid2"><label>Nome<input name="name" required></label><label>Função / instrumento<input name="role" placeholder="Ex.: Regente, Coordenador, Trompetista"></label><label>Grupo<select name="group_type"><option value="COORDENACAO">Coordenação</option><option value="INTEGRANTE">Integrante da Banda</option></select></label><label>Instagram pessoal (opcional)<input name="instagram_url"></label><label>Foto<input type="file" name="photo" accept="image/*"></label><label>Ordem<input type="number" name="sort_order" value="100"></label></div><label>Biografia<textarea name="biography" rows="5"></textarea></label><label class="check"><input type="checkbox" name="published" checked> Publicar</label><button class="primary">CADASTRAR</button></form>
<div class="records people-records"><?php foreach($rows as $r):?><article><?php if($r['photo_path']):?><img src="../<?=e($r['photo_path'])?>" alt=""><?php endif;?><div><span><?=e($r['group_type'])?></span><h3><?=e($r['name'])?></h3><strong><?=e($r['role'])?></strong><p><?=e($r['biography'])?></p></div><form method="post" onsubmit="return confirm('Remover esta pessoa?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger">Excluir</button></form></article><?php endforeach;?></div><?php admin_footer();?>
